 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # Copy colors from the upper-right diagonal stripe onto its continuation,
    # following the lower-left diagonal marker's trajectory.
    h, w = len(grid), len(grid[0])
    # diagonal 5s specify a down-right shift of the diagonal stripe toward left;
    # preserve the original pattern and erase the stripe where the 5-line crosses it.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 5:
                # collision point of 5 with stripe, clear the stripe's colors there
                for k in (0, 1, 2):
                    rr, cc = r, c + k
                    if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] in (6, 9, 8):
                        out[rr][cc] = 0
    return out
